import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2016-JUN-01 -- Ceph Developer Monthly","description":"","frontmatter":{"title":"2016-JUN-01 -- Ceph Developer Monthly","date":"2016-06-02T00:00:00.000Z","updated":"2016-06-03T00:00:00.000Z","tags":["Ceph","Blue Store","Messenger 2 协议","缓存设计","安全性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2016/2016-JUN-01_--_Ceph_Developer_Monthly.md","filePath":"posts/2016/2016-JUN-01_--_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),o={name:"posts/2016/2016-JUN-01_--_Ceph_Developer_Monthly.md"};function a(s,l,n,p,u,_){return i(),t("div",null,[...l[0]||(l[0]=[r('<p>本次会议主要讨论了Ceph的Blue Store缓存设计和Messenger 2协议的改进。</p><h3 id="一、blue-store-缓存设计" tabindex="-1">一、Blue Store 缓存设计 <a class="header-anchor" href="#一、blue-store-缓存设计" aria-label="Permalink to &quot;一、Blue Store 缓存设计&quot;">​</a></h3><p><strong>讨论要点</strong>：</p><ul><li>I/O路径更新：自Juwell版本发布以来，I/O路径已完全重写，元数据结构略有不同，引入了逻辑引用和Blob，Blob可压缩或非压缩，可能包含校验数据。</li><li>缓存设计：Blue Store需要高效地修剪，并管理自己的缓冲区缓存。主要问题是如何在Blue Store中实现缓存，以及使用哪种缓存替换算法。</li><li>缓存结构： <ul><li>全局缓存：简单易实现，但可能导致缓存争用和性能下降。</li><li>按集合缓存：每个集合拥有独立的缓存，但需要额外的锁和复杂的缓存大小调整机制。</li><li>分片缓存：将缓存分成多个分片，每个分片由不同的CPU核心访问，可以提高并发性和性能。</li></ul></li><li>缓存替换算法： <ul><li>LRU算法：简单易实现，但可能导致热点数据被替换。</li><li>MultiQ算法：基于多个LRU列表，可以根据数据的热度进行分层，提高缓存利用率。</li></ul></li></ul><p><strong>决定事项</strong>：</p><ul><li>采用分片缓存结构。</li><li>使用MultiQ算法作为缓存替换算法。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>完善缓存管理代码。</li><li>评估MultiQ算法的性能。</li></ul><h3 id="二、messenger-2-协议" tabindex="-1">二、Messenger 2 协议 <a class="header-anchor" href="#二、messenger-2-协议" aria-label="Permalink to &quot;二、Messenger 2 协议&quot;">​</a></h3><p><strong>讨论要点</strong>：</p><ul><li>降级攻击：如何防止在Exchange中删除消息时影响加密等操作。</li><li>Calamari 项目：讨论了Calamari项目的未来发展方向，包括与Seth Manager的集成。</li><li>协议设计： <ul><li>签名：在消息头中添加签名，以增强安全性。</li><li>协商：客户端和服务器协商支持的协议版本和功能。</li><li>连接：建立连接并进行身份验证。</li><li>消息传递：交换消息。</li><li>断开连接：断开连接并清理资源。</li></ul></li></ul><p><strong>决定事项</strong>：</p><ul><li>在消息头中添加签名。</li><li>客户端和服务器协商支持的协议版本和功能。</li><li>使用简洁的协议设计。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>完善协议实现。</li><li>评估协议性能和安全性。</li></ul><h3 id="三、其他事项" tabindex="-1">三、其他事项 <a class="header-anchor" href="#三、其他事项" aria-label="Permalink to &quot;三、其他事项&quot;">​</a></h3><ul><li>讨论了其他一些议题，包括性能优化、安全性等。</li></ul>',17)])])}const g=e(o,[["render",a]]);export{d as __pageData,g as default};
